.ds-button.ds-compact { color: var(--orange, #ffa064); padding: 2px 10px; }

.ds-button { box-sizing: border-box; display: inline-flex; align-items: center; justify-content: center; gap: 7px; min-height: 28px; padding: 4px 11px; border: 1px solid var(--line, #50516c); border-radius: 4px; color: var(--ink, #d2cfdb); background: transparent; font: 400 12px/1.5 "JetBrains Mono", "SFMono-Regular", Consolas, monospace; font-synthesis: none; white-space: nowrap; text-decoration: none; cursor: pointer; }
.ds-button:hover { border-color: var(--orange, #ffa064); color: var(--orange, #ffa064); }
.ds-button:focus-visible { outline: 1px solid var(--orange, #ffa064); outline-offset: 2px; }
.ds-button:disabled { opacity: .5; cursor: wait; }
.ds-button.ds-text { border-color: transparent; color: var(--muted, #aaa6bb); }
.ds-button.ds-text:hover { color: var(--orange, #ffa064); background: var(--row, #282739); }

.ds-capture-field { display: grid; gap: 7px; font: 400 13px/1.55 "JetBrains Mono", "SFMono-Regular", Consolas, monospace; font-synthesis: none; }
.ds-capture-field label { font-size: 11px; color: var(--muted, #aaa6bb); margin-top: 5px; }
.ds-capture-field input { background: var(--surface, #252435); color: var(--ink, #d2cfdb); border: 1px solid var(--line, #50516c); border-radius: 0; padding: 6px 8px; font: inherit; font-size: 12px; }
.ds-capture-field input::placeholder { color: var(--muted, #aaa6bb); opacity: 1; }
.ds-capture-field input:focus-visible { outline: 1px solid var(--orange, #ffa064); outline-offset: 2px; }

.ds-sidebar { box-sizing: border-box; width: 180px; padding: 22px 12px 12px; background: var(--recessed, #181821); border-right: 1px solid var(--line-soft, #37364d); font: 400 13px/1.55 "JetBrains Mono", "SFMono-Regular", Consolas, monospace; font-synthesis: none; }
.ds-workspace-nav { display: flex; flex-direction: column; flex: 0 0 auto; align-items: stretch; gap: 18px; overflow: visible; min-height: 0; }
.ds-nav-group { display: grid; gap: 2px; }
.ds-nav-group-label { color: var(--muted, #aaa6bb); font-size: 10px; padding: 0 10px 6px; }
.ds-workspace-nav button { box-sizing: border-box; display: flex; align-items: center; justify-content: space-between; width: 100%; min-height: 30px; padding: 5px 10px; border: 0; border-radius: 4px; text-align: left; color: var(--muted, #aaa6bb); background: transparent; box-shadow: none; font: inherit; font-size: 12px; white-space: nowrap; cursor: pointer; }
.ds-workspace-nav button.ds-active { color: var(--ink, #d2cfdb); background: var(--selected, #38354d); box-shadow: inset 2px 0 var(--orange, #ffa064); }
.ds-workspace-nav button:hover:not(.ds-active) { color: var(--ink, #d2cfdb); background: var(--row, #282739); }
.ds-workspace-nav .ds-nav-key { font: inherit; font-size: 10px; color: var(--muted, #aaa6bb); padding: 0; }
.ds-workspace-nav button.ds-active .ds-nav-key { color: var(--orange, #ffa064); }
.ds-workspace-nav button:focus-visible { outline: 1px solid var(--orange, #ffa064); outline-offset: 2px; }
.ds-workspace-nav button:disabled { opacity: .5; cursor: wait; }
@media (max-height: 760px) { .ds-sidebar { box-sizing: border-box; padding-top: 14px; } .ds-workspace-nav { gap: 12px; } .ds-workspace-nav button { box-sizing: border-box; min-height: 27px; padding-top: 3px; padding-bottom: 3px; } .ds-nav-group-label { padding-bottom: 3px; } }
@media (max-height: 570px) { .ds-workspace-nav { gap: 7px; } .ds-nav-group-label { display: none; } .ds-workspace-nav button { box-sizing: border-box; min-height: 24px; } }
@media (max-width: 1100px) { .ds-sidebar { box-sizing: border-box; width: 160px; padding-left: 10px; padding-right: 10px; } }
@media (max-width: 600px) { .ds-sidebar { box-sizing: border-box; width: 112px; padding-left: 5px; padding-right: 5px; } .ds-workspace-nav button { box-sizing: border-box; padding-left: 7px; padding-right: 7px; font-size: 10px; } .ds-workspace-nav .ds-nav-key { display: none; } .ds-nav-group-label { font-size: 9px; } }

.ds-panel { position: relative; min-width: 0; border: 0; border-top: 1px solid var(--line-soft, #37364d); border-radius: 0; padding: 18px 0 0; background: transparent; color: var(--ink, #d2cfdb); font: 400 13px/1.55 "JetBrains Mono", "SFMono-Regular", Consolas, monospace; font-synthesis: none; }
.ds-panel:focus-within { border-color: var(--line-soft, #37364d); }
.ds-section-heading { display: flex; align-items: baseline; justify-content: space-between; gap: 10px; min-height: 18px; padding: 0; }
.ds-panel > .ds-section-heading { position: static; margin: 0 0 16px; pointer-events: auto; }
.ds-section-heading h2 { margin: 0; padding: 0; font-size: 12px; font-weight: 400; color: var(--ink, #d2cfdb); background: transparent; white-space: nowrap; }
.ds-section-heading > span { background: transparent; padding: 0 5px; font-size: 10px; pointer-events: auto; }

.ds-bragbook-evidence { color: var(--ink, #d2cfdb); font: 400 13px/1.55 "JetBrains Mono", "SFMono-Regular", Consolas, monospace; font-synthesis: none; }
.ds-bragbook-evidence blockquote { margin: 14px 0; padding: 8px 12px; border-left: 1px solid var(--line, #50516c); background: var(--recessed, #181821); overflow-wrap: anywhere; }
.ds-bragbook-evidence p { margin: 6px 0; max-width: 72ch; }
.ds-workflow-body { white-space: pre-wrap; overflow-wrap: anywhere; }
.ds-source-link { border: 0; border-radius: 0; background: none; padding: 0; font: 400 11px/1.6 "JetBrains Mono", "SFMono-Regular", Consolas, monospace; color: var(--cyan, #7dc4cf); text-align: left; cursor: pointer; }
.ds-source-link:hover { text-decoration: underline; text-underline-offset: 3px; }
.ds-source-link:focus-visible { outline: 1px solid var(--orange, #ffa064); outline-offset: 2px; }
.ds-source-link:disabled { opacity: .5; cursor: wait; }

.ds-settings-card { border: 1px solid var(--line-soft, #37364d); background: var(--surface, #252435); border-radius: 7px; overflow: hidden; min-width: 0; color: var(--ink, #d2cfdb); font: 400 13px/1.55 "JetBrains Mono", "SFMono-Regular", Consolas, monospace; font-synthesis: none; }
.ds-setting-row { display: grid; grid-template-columns: minmax(0, 1fr) minmax(180px, 290px); align-items: center; gap: 24px; padding: 17px 18px; min-width: 0; }
.ds-setting-row + .ds-setting-row { border-top: 1px solid var(--line-soft, #37364d); }
.ds-setting-copy { min-width: 0; }
.ds-setting-row label { display: block; margin: 0; color: var(--ink, #d2cfdb); font-size: 12px; line-height: 1.5; }
.ds-setting-copy p { margin: 5px 0 0; color: var(--muted, #aaa6bb); font-size: 10px; line-height: 1.7; max-width: 46ch; }
.ds-setting-switch { box-sizing: border-box; appearance: none; -webkit-appearance: none; justify-self: end; flex: none; width: 34px; height: 20px; min-height: 0; border: 1px solid var(--line, #50516c); border-radius: 20px; background: var(--recessed, #181821); background-image: radial-gradient(circle at 9px 50%, var(--muted, #aaa6bb) 0 6px, transparent 6.5px); padding: 0; margin: 0; position: relative; cursor: pointer; }
.ds-setting-switch:checked { background-color: var(--orange, #ffa064); border-color: var(--orange, #ffa064); background-image: radial-gradient(circle at calc(100% - 9px) 50%, var(--on-accent, #191824) 0 6px, transparent 6.5px); }
.ds-setting-switch:disabled { cursor: default; opacity: .5; }
.ds-setting-switch:focus-visible { outline: 1px solid var(--orange, #ffa064); outline-offset: 2px; }
@media (max-width: 1100px) { .ds-setting-row { grid-template-columns: minmax(0, 1fr) minmax(160px, 240px); gap: 18px; } }
@media (max-width: 760px) { .ds-setting-row { grid-template-columns: minmax(0, 1fr); gap: 12px; padding: 16px; } .ds-setting-row:has(> .ds-setting-switch) { grid-template-columns: minmax(0, 1fr) auto; } }
